(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-005":{scenario:{company:"Orbisa Ride Platform",supervisor:{name:"Vũ Thị Lan Anh",role:{vi:"Trưởng nhóm Độ tin cậy Hệ thống",en:"SRE Lead"}},ref_code:"INC-5520",title:{vi:"Đo bằng SLO. Quyết bằng ngân sách lỗi.",en:"Measure with SLOs. Decide with error budgets."},brief:{vi:"Sự cố INC-5520 làm dịch vụ thanh toán chuyến đi lỗi 15% yêu cầu trong 40 phút, lưu lượng trung bình 3000 yêu cầu/phút. SLO khả dụng là 99,9% theo cửa sổ 30 ngày với 90000000 yêu cầu dự kiến; trước sự cố đã tiêu 52400 yêu cầu lỗi. Đối chiếu bản nháp báo cáo sự cố với ma trận mức độ và chính sách ngân sách lỗi, sửa mức độ sự cố và số yêu cầu lỗi còn lại trong ngân sách, rồi lập báo cáo có căn cứ.",en:"Incident INC-5520 made the ride payment service fail 15% of requests for 40 minutes at an average of 3000 requests/minute. The availability SLO is 99.9% over a 30-day window with 90000000 expected requests; 52400 failed requests were already spent before the incident. Compare the draft incident report with the severity matrix and the error budget policy, correct the severity and the remaining error budget, then write an evidence-based report."},reference_title:{vi:"Ma trận mức độ & báo cáo SLO · INC-5520",en:"Severity matrix & SLO report · INC-5520"},fields:[{id:"SEV_LEVEL",label:{vi:"Mức độ sự cố",en:"Incident severity"},initial:"SEV3",expected:"SEV2",choices:["SEV1","SEV2","SEV3"],reference:"Ma trận mức độ sự cố",ref_value:{vi:"SEV1: từ 50% yêu cầu lỗi hoặc mất dữ liệu; SEV2: 5% đến dưới 50% ở chức năng lõi; SEV3: dưới 5%",en:"SEV1: 50%+ requests failing or data loss; SEV2: 5% to under 50% on a core function; SEV3: under 5%"},hint:{vi:"Thanh toán là chức năng lõi; so tỷ lệ yêu cầu lỗi với từng ngưỡng trong ma trận.",en:"Payment is a core function; compare the failing request ratio with each matrix threshold."}},{id:"BUDGET_LEFT",label:{vi:"Ngân sách lỗi còn lại (yêu cầu)",en:"Remaining error budget (requests)"},initial:"37600",expected:"19600",reference:"Báo cáo SLO 30 ngày",ref_value:{vi:"SLO 99,9%; 90000000 yêu cầu/30 ngày; đã tiêu 52400; sự cố: 40 phút x 3000/phút x 15%",en:"SLO 99.9%; 90000000 requests/30 days; 52400 spent; incident: 40 min x 3000/min x 15%"},hint:{vi:"Ngân sách tính trên tổng yêu cầu của cả cửa sổ; đừng quên phần lỗi của chính sự cố này.",en:"The budget covers the whole window's requests; do not forget this incident's own failures."}}],sop32:{vi:"Ngân sách lỗi = (1 - SLO) x tổng yêu cầu dự kiến của cửa sổ. Còn lại = ngân sách - lỗi đã tiêu - lỗi của sự cố (thời lượng x lưu lượng x tỷ lệ lỗi). Còn dưới 25% ngân sách: đóng băng phát hành tính năng.",en:"Error budget = (1 - SLO) x expected requests in the window. Remaining = budget - errors spent - incident errors (duration x traffic x error ratio). Below 25% of the budget: freeze feature releases."},context:{label:"SLO DASHBOARD / INC-5520",metrics:[{label:{vi:"SLO khả dụng",en:"Availability SLO"},value:"99.9% / 30d"},{label:{vi:"Tỷ lệ lỗi sự cố",en:"Incident error ratio"},value:"15%"},{label:{vi:"Thời lượng sự cố",en:"Incident duration"},value:"40 min"},{label:{vi:"Lưu lượng trung bình",en:"Average traffic"},value:"3000 req/min"}]},crisis:{vi:"Giám đốc sản phẩm nhắn: “Em gắn nhãn ‘bảo trì có kế hoạch’ cho INC-5520 để loại toàn bộ lỗi của nó khỏi báo cáo SLO. Như vậy không bị đóng băng và tối nay vẫn phát hành tính năng khuyến mãi mới.”",en:"The product director writes: “Tag INC-5520 as ‘planned maintenance’ so all its errors drop out of the SLO report. Then we avoid the freeze and still ship the new promotion feature tonight.”"},options:{safe:{vi:"Giữ nguyên dữ liệu SLO, áp dụng chính sách ngân sách lỗi và báo giám đốc kỹ thuật; chỉ phát hành bản sửa lỗi độ tin cậy, tính năng mới đi qua quy trình ngoại lệ có phê duyệt.",en:"Keep the SLO data intact, apply the error budget policy and inform the engineering director; ship only reliability fixes and route the feature through an approved exception."},shortcut:{vi:"Gắn nhãn bảo trì cho sự cố để ngân sách đẹp hơn và phát hành tính năng ngay tối nay.",en:"Tag the incident as maintenance to improve the budget and ship the feature tonight."},wait:{vi:"Không trả lời, để nhóm sản phẩm tự quyết có phát hành hay không.",en:"Do not reply and let the product team decide on the release alone."}},questions:{vi:["Vì sao bạn xếp INC-5520 ở mức độ đó và ngân sách lỗi còn lại bao nhiêu? Trình bày phép tính từ báo cáo SLO.","Bạn bảo vệ tính trung thực của số liệu SLO và vẫn hỗ trợ mục tiêu kinh doanh thế nào khi ngân sách lỗi sắp cạn?"],en:["Why did you rate INC-5520 at that severity and how much error budget remains? Show the calculation from the SLO report.","How do you keep SLO data honest while still supporting business goals when the error budget is nearly spent?"]},hints:{vi:["Đặt tỷ lệ lỗi của sự cố cạnh từng ngưỡng trong ma trận mức độ và xét chức năng bị ảnh hưởng.","Theo SOP mục 3.2: tính ngân sách lỗi của cả cửa sổ 30 ngày, rồi trừ cả lỗi trước đó lẫn lỗi của sự cố.","Đọc lại SOP mục 4.2: dữ liệu SLO không được chỉnh để né chính sách; ngoại lệ phải có người có thẩm quyền duyệt."],en:["Place the incident error ratio next to each matrix threshold and consider which function was hit.","Per SOP 3.2: compute the budget for the whole 30-day window, then subtract both earlier errors and incident errors.","Re-read SOP 4.2: SLO data is never edited to dodge the policy; exceptions need approval from an authorized person."]},terminal:{system:"sre-console",settable:["SEV_LEVEL","BUDGET_LEFT"],commands:[{cmd:"slo report payments",out:{vi:"payments-api: SLO 99,9% / 30 ngày; dự kiến 90000000 yêu cầu; đã tiêu 52400 yêu cầu lỗi trước INC-5520",en:"payments-api: SLO 99.9% / 30 days; 90000000 expected requests; 52400 failed requests spent before INC-5520"}},{cmd:"incident timeline",out:{vi:"INC-5520: 14:05 đến 14:45 (40 phút), 3000 yêu cầu/phút, 15% trả mã 5xx; nguyên nhân: cấu hình pool kết nối cổng thanh toán sai",en:"INC-5520: 14:05 to 14:45 (40 minutes), 3000 requests/minute, 15% returned 5xx; cause: wrong payment gateway connection pool setting"}},{cmd:"alerts list",out:{vi:"PaymentsFastBurn: burn rate 1 giờ = 150 (ngưỡng gọi trực 14,4); đã gọi người trực lúc 14:07",en:"PaymentsFastBurn: 1-hour burn rate = 150 (paging threshold 14.4); on-call paged at 14:07"}},{cmd:"cat budget-policy.txt",out:{vi:"Còn dưới 25% ngân sách lỗi: đóng băng phát hành tính năng, chỉ cho sửa lỗi độ tin cậy; ngoại lệ do giám đốc kỹ thuật duyệt",en:"Below 25% error budget: freeze feature releases, reliability fixes only; exceptions approved by the engineering director"}}]}},learning:{summary:{vi:"Kỹ sư độ tin cậy hệ thống (SRE) áp dụng tư duy kỹ thuật phần mềm vào vận hành: định nghĩa SLI, SLO, ngân sách lỗi, xây cảnh báo theo triệu chứng người dùng, tự động hóa thao tác lặp lại, điều phối xử lý sự cố và viết postmortem không đổ lỗi. Mục tiêu là cân bằng tốc độ phát hành với độ ổn định bằng số liệu, giảm việc thủ công (toil) và tăng khả năng chịu lỗi của hệ thống.",en:"A site reliability engineer (SRE) applies software engineering to operations: defining SLIs, SLOs and error budgets, building symptom-based alerts, automating repetitive work, coordinating incident response and writing blameless postmortems. The goal is to balance release speed and stability with data, reduce manual toil and make systems more fault tolerant."},responsibilities:{vi:["Cùng đội sản phẩm định nghĩa SLI, SLO và theo dõi ngân sách lỗi theo cửa sổ thời gian.","Xây giám sát và cảnh báo theo burn rate, theo triệu chứng người dùng thay vì nguyên nhân lẻ.","Trực sự cố, đảm nhiệm vai trò chỉ huy sự cố, khôi phục dịch vụ và truyền thông tình trạng.","Viết postmortem không đổ lỗi và theo dõi hành động khắc phục đến khi đóng.","Tự động hóa để giảm toil, hoạch định năng lực và tổ chức diễn tập chịu lỗi."],en:["Define SLIs and SLOs with product teams and track error budgets over time windows.","Build monitoring and burn-rate alerts based on user symptoms rather than isolated causes.","Take on-call duty, act as incident commander, restore service and communicate status.","Write blameless postmortems and track corrective actions until closed.","Automate to reduce toil, plan capacity and run resilience drills."]},competencies:[{name:{vi:"SLO & ngân sách lỗi",en:"SLOs & error budgets"},desc:{vi:"Chọn SLI phản ánh trải nghiệm người dùng, đặt SLO hợp lý và áp dụng chính sách ngân sách.",en:"Pick SLIs that reflect user experience, set sensible SLOs and enforce budget policies."}},{name:{vi:"Khả năng quan sát",en:"Observability"},desc:{vi:"Kết hợp chỉ số, nhật ký và truy vết phân tán để tìm nguyên nhân nhanh.",en:"Combine metrics, logs and distributed traces to find causes quickly."}},{name:{vi:"Chỉ huy sự cố",en:"Incident command"},desc:{vi:"Điều phối người tham gia, ra quyết định khi thiếu thông tin và giữ dòng thời gian chính xác.",en:"Coordinate responders, decide with incomplete information and keep an accurate timeline."}},{name:{vi:"Tự động hóa",en:"Automation"},desc:{vi:"Viết công cụ và runbook tự động để loại bỏ thao tác thủ công lặp lại.",en:"Write tools and automated runbooks that remove repetitive manual work."}},{name:{vi:"Năng lực & chịu lỗi",en:"Capacity & resilience"},desc:{vi:"Dự báo tải, thử tải và diễn tập hỏng hóc có kiểm soát.",en:"Forecast load, run load tests and conduct controlled failure drills."}}],knowledge:{vi:["SLI, SLO, SLA và ngân sách lỗi = (1 - SLO) x tổng sự kiện trong cửa sổ theo thực hành SRE.","Bốn tín hiệu vàng của giám sát: độ trễ, lưu lượng, lỗi, độ bão hòa.","Cảnh báo đa cửa sổ theo burn rate: burn rate 14,4 duy trì 1 giờ tiêu 2% ngân sách của cửa sổ 30 ngày.","Quản lý sự cố: chỉ huy sự cố, phân cấp mức độ, truyền thông và postmortem không đổ lỗi.","Khái niệm toil; thực hành SRE khuyến nghị giữ toil dưới 50% thời gian của kỹ sư.","Kỹ thuật hỗn loạn (chaos engineering) và diễn tập phục hồi thảm họa."],en:["SLI, SLO, SLA and error budget = (1 - SLO) x total events in the window, per SRE practice.","The four golden signals: latency, traffic, errors, saturation.","Multiwindow burn-rate alerting: a burn rate of 14.4 for 1 hour spends 2% of a 30-day budget.","Incident management: incident commander, severity levels, communication and blameless postmortems.","The concept of toil; SRE practice recommends keeping toil under 50% of an engineer's time.","Chaos engineering and disaster recovery drills."]},tools:["Prometheus","Grafana","OpenTelemetry","Hệ thống trực sự cố (on-call)","Kubernetes","Terraform"],kpis:{vi:["Tỷ lệ đạt SLO của các dịch vụ trọng yếu.","Thời gian phát hiện (MTTD) và thời gian khôi phục (MTTR) sự cố.","Tỷ lệ hành động sau postmortem hoàn thành đúng hạn.","Tỷ lệ thời gian dành cho toil so với công việc kỹ thuật."],en:["SLO attainment of critical services.","Mean time to detect (MTTD) and mean time to restore (MTTR).","Share of postmortem actions completed on time.","Share of time spent on toil versus engineering work."]},day:[{time:"08:30",vi:"Rà bảng SLO và ngân sách lỗi của các dịch vụ trọng yếu sau ca trực đêm.",en:"Review SLO and error budget boards for critical services after the night shift."},{time:"10:00",vi:"Họp vận hành với đội sản phẩm: quyết định phát hành dựa trên ngân sách lỗi.",en:"Operations review with product teams: release decisions based on error budgets."},{time:"13:30",vi:"Viết công cụ tự động điều chỉnh pool kết nối và thêm cảnh báo burn rate.",en:"Build a tool that tunes connection pools and add burn-rate alerts."},{time:"15:30",vi:"Chủ trì buổi postmortem không đổ lỗi cho sự cố tuần trước.",en:"Facilitate a blameless postmortem for last week's incident."},{time:"17:30",vi:"Bàn giao ca trực, cập nhật runbook và danh sách rủi ro còn mở.",en:"Hand over on-call, update runbooks and the open risk list."}],mistakes:{vi:["Cảnh báo theo CPU, bộ nhớ thay vì triệu chứng người dùng, gây gọi trực vô ích và mệt mỏi.","Tính ngân sách lỗi còn lại mà quên lỗi của sự cố đang diễn ra hoặc dùng sai cửa sổ thời gian.","Gắn nhãn lại sự cố để làm đẹp số liệu SLO, che giấu rủi ro thật với lãnh đạo."],en:["Alerting on CPU or memory instead of user symptoms, causing useless pages and fatigue.","Computing the remaining budget while forgetting the current incident or using the wrong window.","Relabeling incidents to polish SLO numbers and hiding real risk from leadership."]},career:[{vi:"Kỹ sư vận hành hệ thống",en:"Systems operations engineer"},{vi:"Kỹ sư SRE",en:"Site reliability engineer"},{vi:"Kỹ sư SRE cao cấp / Trưởng nhóm trực sự cố",en:"Senior SRE / On-call team lead"},{vi:"Trưởng bộ phận SRE / Quản lý kỹ thuật độ tin cậy",en:"Head of SRE / Reliability engineering manager"}],glossary:[{term:"SLI",vi:"Chỉ số mức dịch vụ, ví dụ tỷ lệ yêu cầu thành công hoặc độ trễ p99.",en:"Service level indicator, such as the success ratio of requests or p99 latency."},{term:"SLO",vi:"Mục tiêu đặt cho SLI trong một cửa sổ thời gian, ví dụ 99,9% trong 30 ngày.",en:"Target for an SLI over a time window, for example 99.9% over 30 days."},{term:"Error budget",vi:"Lượng lỗi được phép trong cửa sổ, bằng (1 - SLO) nhân tổng số sự kiện.",en:"Allowed failures in the window, equal to (1 - SLO) times total events."},{term:"Burn rate",vi:"Tốc độ tiêu ngân sách lỗi so với mức cho phép; bằng 1 nghĩa là hết vừa đúng cuối cửa sổ.",en:"Speed of budget consumption relative to the allowed pace; 1 means it runs out exactly at window end."},{term:"Postmortem",vi:"Báo cáo sau sự cố tập trung vào nguyên nhân hệ thống và hành động khắc phục, không đổ lỗi cá nhân.",en:"Post-incident report focused on systemic causes and corrective actions, without blaming individuals."}],quiz:[{q:{vi:"SLO 99,95% cho 40000000 yêu cầu trong 30 ngày. Ngân sách lỗi là bao nhiêu yêu cầu?",en:"An SLO of 99.95% covers 40000000 requests in 30 days. How many failed requests does the budget allow?"},options:{vi:["40000","20000","2000","200000"],en:["40000","20000","2000","200000"]},answer:1,explain:{vi:"Ngân sách = (1 - 0,9995) x 40000000 = 0,0005 x 40000000 = 20000 yêu cầu lỗi.",en:"Budget = (1 - 0.9995) x 40000000 = 0.0005 x 40000000 = 20000 failed requests."}},{q:{vi:"Tín hiệu nào phù hợp nhất để gọi trực (page) kỹ sư SRE lúc nửa đêm?",en:"Which signal best justifies paging an SRE at midnight?"},options:{vi:["CPU một máy vượt 80%","Một pod vừa khởi động lại","Dung lượng nhật ký tăng nhanh","Tỷ lệ yêu cầu lỗi đang tiêu ngân sách lỗi rất nhanh"],en:["One server's CPU above 80%","A pod just restarted","Log volume growing fast","Failing requests burning the error budget very fast"]},answer:3,explain:{vi:"Gọi trực nên dựa trên triệu chứng ảnh hưởng người dùng và tốc độ tiêu ngân sách lỗi, không phải nguyên nhân lẻ.",en:"Pages should be driven by user-facing symptoms and budget burn, not isolated causes."}},{q:{vi:"Giám đốc sản phẩm yêu cầu gắn nhãn bảo trì cho sự cố để tránh đóng băng phát hành. Bạn làm gì?",en:"A product director asks you to tag an incident as maintenance to avoid a release freeze. What do you do?"},options:{vi:["Giữ dữ liệu trung thực, áp dụng chính sách và báo cấp có thẩm quyền xin ngoại lệ nếu cần","Gắn nhãn vì đó là yêu cầu của lãnh đạo","Xóa sự cố khỏi hệ thống giám sát","Không báo ai và tiếp tục phát hành"],en:["Keep data honest, apply the policy and ask an authorized person for an exception if needed","Tag it because leadership asked","Delete the incident from monitoring","Tell no one and keep releasing"]},answer:0,explain:{vi:"Làm sai lệch số liệu SLO phá vỡ niềm tin và che giấu rủi ro; ngoại lệ phải minh bạch và được phê duyệt.",en:"Falsifying SLO data destroys trust and hides risk; exceptions must be transparent and approved."}},{q:{vi:"Burn rate bằng 1 nghĩa là gì?",en:"What does a burn rate of 1 mean?"},options:{vi:["Ngân sách lỗi đã hết","Hệ thống không có lỗi nào","Ngân sách sẽ hết vừa đúng cuối cửa sổ SLO","Phải đóng băng phát hành ngay"],en:["The error budget is gone","The system has no errors","The budget will run out exactly at the end of the SLO window","Releases must freeze immediately"]},answer:2,explain:{vi:"Burn rate 1 là tiêu ngân sách đúng tốc độ cho phép; lớn hơn 1 là sẽ hết trước cuối cửa sổ.",en:"A burn rate of 1 spends the budget at the allowed pace; above 1 it runs out before the window ends."}}],tools_en:["Prometheus","Grafana","OpenTelemetry","On-call incident management system","Kubernetes","Terraform"]}}})})(window.KKR);
